INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion (Frank)$batch01$, $batch01$Today, one needs a formal education to make crucial technological contributions.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Since Edison's day, technology has developed so much that today's contributors need far more extensive technical knowledge than he did.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Frank may be right about the need for *knowledge*. But he has switched from knowledge to *formal education*. Someone could acquire deep technical knowledge through independent study, apprenticeship, work, or other routes. Edison having little schooling does not prove that today's knowledge demands can be met without schooling, but Frank's reply likewise fails to establish that schooling is required.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the distinction between needing technical knowledge and needing formal education.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT117-S3-Q4$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
